frappe.ui.form.on('HD Ticket', {

    refresh(frm) {

        // ===================================
        // SHOW ONLY ON SAVED DOCUMENTS
        // ===================================

        if (!frm.is_new()) {

            frm.add_custom_button(

                'Transfer Department',

                () => {

                    frappe.prompt(

                        [

                            {

                                label: 'Department',

                                fieldname: 'department',

                                fieldtype: 'Link',

                                options: 'Department',

                                reqd: 1
                            }

                        ],

                        (values) => {

                            // ===================================
                            // UPDATE DEPARTMENT
                            // ===================================

                            frm.set_value(
                                'custom_department',
                                values.department
                            );


                            // ===================================
                            // UPDATE SLA BASED ON DEPARTMENT
                            // ===================================

                            if (
                                values.department ==
                                "Development - CYN"
                            ) {

                                frm.set_value(
                                    'service_level',
                                    'Development SLA'
                                );
                            }


                            else if (
                                values.department ==
                                "HR - CYN"
                            ) {

                                frm.set_value(
                                    'service_level',
                                    'HR SLA'
                                );
                            }


                            else if (
                                values.department ==
                                "Accounts - CYN"
                            ) {

                                frm.set_value(
                                    'service_level',
                                    'Accounts SLA'
                                );
                            }


                            else if (
                                values.department ==
                                "IT - CYN"
                            ) {

                                frm.set_value(
                                    'service_level',
                                    'IT SLA'
                                );
                            }


                            else if (
                                values.department ==
                                "Sales - CYN"
                            ) {

                                frm.set_value(
                                    'service_level',
                                    'Sales SLA'
                                );
                            }


                            else {

                                frm.set_value(
                                    'service_level',
                                    'Support SLA'
                                );
                            }


                            // ===================================
                            // SAVE DOCUMENT
                            // ===================================

                            frm.save();


                            // ===================================
                            // SUCCESS MESSAGE
                            // ===================================

                            frappe.msgprint(
                                'Ticket transferred successfully'
                            );

                        },

                        'Transfer Ticket',

                        'Transfer'

                    );

                }

            );

        }

    }

});

