frappe.listview_settings['Attendance'] = {

    onload: function(listview) {

        listview.page.add_inner_button(

            'Mark Attendance',

            function () {

                let d = new frappe.ui.Dialog({

                    title: 'Mark Attendance',

                    fields: [

                        // ===================================
                        // EMPLOYEE
                        // ===================================

                        {
                            label: 'For Employee',

                            fieldname: 'employee',

                            fieldtype: 'Link',

                            options: 'Employee',

                            reqd: 1,

                            onchange: generate_dates
                        },

                        // ===================================
                        // FROM DATE
                        // ===================================

                        {
                            label: 'Start',

                            fieldname: 'from_date',

                            fieldtype: 'Date',

                            reqd: 1,

                            onchange: generate_dates
                        },

                        // ===================================
                        // TO DATE
                        // ===================================

                        {
                            label: 'End',

                            fieldname: 'to_date',

                            fieldtype: 'Date',

                            reqd: 1,

                            onchange: generate_dates
                        },

                        // ===================================
                        // STATUS
                        // ===================================

                        {
                            label: 'Status',

                            fieldname: 'status',

                            fieldtype: 'Select',

                            options: [
                                '',
                                'Present',
                                'Absent',
                                'On Leave',
                                'Work From Home'
                            ].join('\n'),

                            reqd: 1,

                            onchange: function () {

                                let status =
                                    d.get_value('status');

                                // ===============================
                                // WORK FROM HOME
                                // ===============================

                                if (
                                    status ===
                                    "Work From Home"
                                ) {

                                    d.set_df_property(
                                        'custom_wfh_type',
                                        'hidden',
                                        0
                                    );

                                    d.set_df_property(
                                        'custom_wfh_type',
                                        'reqd',
                                        1
                                    );

                                } else {

                                    d.set_value(
                                        'custom_wfh_type',
                                        ''
                                    );

                                    d.set_df_property(
                                        'custom_wfh_type',
                                        'hidden',
                                        1
                                    );

                                    d.set_df_property(
                                        'custom_wfh_type',
                                        'reqd',
                                        0
                                    );
                                }

                                // ===============================
                                // ON LEAVE
                                // ===============================

                                if (
                                    status ===
                                    "On Leave"
                                ) {

                                    d.set_df_property(
                                        'leave_type',
                                        'hidden',
                                        0
                                    );

                                    d.set_df_property(
                                        'leave_type',
                                        'reqd',
                                        1
                                    );

                                } else {

                                    d.set_value(
                                        'leave_type',
                                        ''
                                    );

                                    d.set_df_property(
                                        'leave_type',
                                        'hidden',
                                        1
                                    );

                                    d.set_df_property(
                                        'leave_type',
                                        'reqd',
                                        0
                                    );
                                }

                                // ===============================
                                // REFRESH FIELDS
                                // ===============================

                                d.refresh_field(
                                    'custom_wfh_type'
                                );

                                d.refresh_field(
                                    'leave_type'
                                );
                            }
                        },

                        // ===================================
                        // SHIFT
                        // ===================================

                        {
                            label: 'Shift',

                            fieldname: 'shift',

                            fieldtype: 'Link',

                            options: 'Shift Type'
                        },

                        // ===================================
                        // WFH TYPE
                        // ===================================

                        {
                            label: 'WFH Type',

                            fieldname: 'custom_wfh_type',

                            fieldtype: 'Select',

                            options: [
                                '',
                                'WFH company',
                                'WFH employee'
                            ].join('\n'),

                            hidden: 1
                        },

                        // ===================================
                        // LEAVE TYPE
                        // ===================================

                        {
                            label: 'Leave Type',

                            fieldname: 'leave_type',

                            fieldtype: 'Link',

                            options: 'Leave Type',

                            hidden: 1
                        },

                        // ===================================
                        // HTML FIELD
                        // ===================================

                        {
                            fieldtype: 'HTML',

                            fieldname: 'dates_html'
                        }
                    ],

                    // ===================================
                    // PRIMARY ACTION
                    // ===================================

                    primary_action_label:
                        'Mark Attendance',

                    primary_action:
                        async function(values) {

                        let selected_dates = [];

                        d.$wrapper.find(
                            '.attendance-date:checked'
                        ).each(function () {

                            selected_dates.push(
                                $(this).val()
                            );
                        });

                        if (
                            !selected_dates.length
                        ) {

                            frappe.msgprint(
                                "Please select at least one date"
                            );

                            return;
                        }

                        let created_count = 0;

                        // ===================================
                        // LOOP DATES
                        // ===================================

                        for (let date of selected_dates) {

                            // ---------------------------
                            // CHECK EXISTING
                            // ---------------------------

                            let existing =
                                await frappe.call({

                                method:
                                    "frappe.client.get_list",

                                args: {

                                    doctype:
                                        "Attendance",

                                    filters: {

                                        employee:
                                            values.employee,

                                        attendance_date:
                                            date
                                    },

                                    fields: ["name"],

                                    limit_page_length: 1
                                }
                            });

                            // Skip existing
                            if (
                                existing.message &&
                                existing.message.length > 0
                            ) {

                                continue;
                            }

                            // ---------------------------
                            // CREATE DOC
                            // ---------------------------

                            let doc = {

                                doctype:
                                    "Attendance",

                                employee:
                                    values.employee,

                                attendance_date:
                                    date,

                                status:
                                    values.status,

                                shift:
                                    values.shift || null,

                                leave_type:
                                    values.leave_type || null,

                                custom_wfh_type:
                                    values.custom_wfh_type || null
                            };

                            // ---------------------------
                            // INSERT
                            // ---------------------------

                            let inserted =
                                await frappe.call({

                                method:
                                    "frappe.client.insert",

                                args: {
                                    doc
                                }
                            });

                            // ---------------------------
                            // SUBMIT
                            // ---------------------------

                            await frappe.call({

                                method:
                                    "frappe.client.submit",

                                args: {
                                    doc:
                                        inserted.message
                                }
                            });

                            created_count++;
                        }

                        // ===================================
                        // MESSAGE
                        // ===================================

                        if (created_count > 0) {

                            frappe.msgprint({

                                title:
                                    'Attendance Marked',

                                indicator:
                                    'green',

                                message: `
                                    Successfully marked
                                    ${created_count}
                                    attendance records.
                                `
                            });

                        } else {

                            frappe.msgprint({

                                title:
                                    'No New Attendance',

                                indicator:
                                    'orange',

                                message: `
                                    All attendance
                                    records already exist.
                                `
                            });
                        }

                        d.hide();

                        frappe.listview.refresh();
                    }
                });

                d.show();

                // ===================================
                // GENERATE DATES
                // ===================================

                function generate_dates() {

                    let from =
                        d.get_value('from_date');

                    let to =
                        d.get_value('to_date');

                    let emp =
                        d.get_value('employee');

                    if (
                        !from ||
                        !to ||
                        !emp
                    ) {
                        return;
                    }

                    let start =
                        new Date(from);

                    let end =
                        new Date(to);

                    let html = `

                        <div
                            style="margin-bottom:10px;"
                        >

                            <button
                                class="
                                btn
                                btn-xs
                                btn-primary
                                select-all
                                "
                            >
                                Select All
                            </button>

                            <button
                                class="
                                btn
                                btn-xs
                                btn-default
                                unselect-all
                                "
                            >
                                Unselect All
                            </button>

                        </div>
                    `;

                    while (start <= end) {

                        let date =
                            frappe.datetime.obj_to_str(
                                start
                            );

                        html += `

                            <div>

                                <input
                                    type="checkbox"

                                    class="
                                    attendance-date
                                    "

                                    value="${date}"

                                    checked
                                >

                                ${date}

                            </div>
                        `;

                        start.setDate(
                            start.getDate() + 1
                        );
                    }

                    d.fields_dict
                    .dates_html
                    .$wrapper
                    .html(html);

                    // ===================================
                    // SELECT ALL
                    // ===================================

                    d.$wrapper.find(
                        '.select-all'
                    ).click(() => {

                        d.$wrapper.find(
                            '.attendance-date'
                        ).prop(
                            'checked',
                            true
                        );
                    });

                    // ===================================
                    // UNSELECT ALL
                    // ===================================

                    d.$wrapper.find(
                        '.unselect-all'
                    ).click(() => {

                        d.$wrapper.find(
                            '.attendance-date'
                        ).prop(
                            'checked',
                            false
                        );
                    });
                }
            }
        );
    }
};

frappe.ui.form.on('Project', {
    refresh: function(frm) {

        let project = frm.doc.name;

        frappe.call({
            method: "frappe.client.get_list",
            args: {
                doctype: "Task",
                filters: { project: project },
                fields: ["name"]
            },
            callback: function(res) {

                let task_names = (res.message || []).map(t => t.name);

                frappe.call({
                    method: "frappe.client.get_list",
                    args: {
                        doctype: "File",
                        filters: [
                            ["attached_to_doctype", "in", ["Project", "Task"]],
                            ["attached_to_name", "in", [project, ...task_names]]
                        ],
                        fields: ["file_name", "file_url"]
                    },
                    callback: function(files) {

                        let html = "<h5>Project Assets</h5><ul>";

                        (files.message || []).forEach(f => {
                            html += `<li><a href="${f.file_url}" target="_blank">${f.file_name}</a></li>`;
                        });

                        html += "</ul>";

                        // 🔥 IMPORTANT: use your field name
                        if (frm.fields_dict.custom_asstes) {
                            frm.fields_dict.custom_asstes.$wrapper.html(html);
                        }
                    }
                });
            }
        });
    }
});

frappe.ui.form.on('Salary Slip', {

    refresh(frm) {
        fetch_wfh_days(frm);
    },

    employee(frm) {
        fetch_wfh_days(frm);
    },

    start_date(frm) {
        fetch_wfh_days(frm);
    },

    end_date(frm) {
        fetch_wfh_days(frm);
    }
});

function fetch_wfh_days(frm) {

    if (!frm.doc.employee || !frm.doc.start_date || !frm.doc.end_date) {
        return;
    }

    frappe.call({
        method: "frappe.client.get_list",
        args: {
            doctype: "Attendance",
            filters: {
                employee: frm.doc.employee,
                attendance_date: ["between", [frm.doc.start_date, frm.doc.end_date]],
                status: "Work From Home",
                docstatus: 1
            },
            fields: ["custom_wfh_type"],
            limit_page_length: 1000
        },
        callback: function(r) {

            let employee_wfh = 0;

            if (r.message) {
                r.message.forEach(row => {
                    let type = (row.custom_wfh_type || "").trim();

                    if (type === "WFH employee") {
                        employee_wfh++;
                    }
                });
            }

            // ✅ Only employee WFH
            frm.set_value("custom_wfh_days", employee_wfh);
        }
    });
}

