function set_advance_account(frm) {
    if (!frm.doc.company) {
        return;
    }
    frappe.db.get_value('Company', frm.doc.company, 'default_receivable_account', (r) => {
        if (r && r.default_receivable_account) {
            frm.set_value('advance_account', r.default_receivable_account);
        }
    });
}

frappe.ui.form.on('Timesheet', {

    custom_amc_contract: function(frm) {

        if (!frm.doc.custom_amc_contract) return;

        frappe.call({
            method: "frappe.client.get",
            args: {
                doctype: "AMC Contract",
                name: frm.doc.custom_amc_contract
            },
            callback: function(r) {

                if (!r.message) return;

                let amc = r.message;

                let rows = amc.table_bxbb || [];

                frm.clear_table("time_logs");

                rows.forEach(row => {

                    let child = frm.add_child("time_logs");


                    child.custom_ticket = row.ticket || "";


                    // child.hours = row.hours_usage;


                    child.project = frm.doc.project || amc.project;


                    let now = frappe.datetime.now_datetime();
                    child.from_time = now;
                    child.to_time = now;   // same time → no auto hours
                });

                frm.refresh_field("time_logs");

                frappe.msgprint(`Loaded ${rows.length} tickets`);
            }
        });
    }
});

