    refresh: calculate_hours,
    employee: calculate_hours,
    start_date: calculate_hours,
    end_date: calculate_hours
});

function calculate_hours(frm) {
    if (!frm.doc.employee || !frm.doc.start_date || !frm.doc.end_date) return;
    frappe.call({
        method: 'frappe.client.get_list',
        args: {
            doctype: 'Employee Checkin',
            filters: [
                ['employee', '=', frm.doc.employee],
                ['time', 'between', [frm.doc.start_date, frm.doc.end_date + ' 23:59:59']]
            ],
            fields: ['time', 'log_type'],
            order_by: 'time asc',
            limit_page_length: 500
        },
        callback: function(r) {
            if (!r.message) return;
            let checkins = r.message;
            let daily_hours = {};
            let i = 0;
            while (i < checkins.length - 1) {
                if (checkins[i].log_type === 'IN' && checkins[i+1].log_type === 'OUT') {
                    let inn = new Date(checkins[i].time);
                    let out = new Date(checkins[i+1].time);
                    let hours = (out - inn) / (1000 * 60 * 60);
                    let day = checkins[i].time.substring(0, 10);
                    daily_hours[day] = (daily_hours[day] || 0) + hours;
                    i += 2;
                } else {
                    i++;
                }
            }

            let total_insufficient = 0;
            let total_overtime = 0;

            for (let day in daily_hours) {
                if (daily_hours[day] < 8) {
                    total_insufficient += (8 - daily_hours[day]);
                } else if (daily_hours[day] > 8) {
                    total_overtime += (daily_hours[day] - 8);
                }
            }

            frm.set_value('custom_insufficient_hours', total_insufficient);
            frm.set_value('custom_overtime_hours', total_overtime);
        }
    });
}

