function populate_items_from_deal(frm) {
    if (!frm.is_new()) return;
    if (frm.doc.quotation_to !== "CRM Deal") return;
    if (frm.__deal_items_loaded) return;

    let existing = frm.doc.items || [];
    if (existing.length > 0 && existing[0].item_code) return;

    let deal = frm.doc.party_name;
    if (!deal) return;

    frm.__deal_items_loaded = true;

    frappe.call({
        method: "frappe.client.get",
        args: { doctype: "CRM Deal", name: deal },
        callback(r) {
            if (!r.message || !(r.message.products || []).length) return;

            let products = r.message.products;

            // Collect item codes to fetch their UOMs
            let item_codes = products
                .map(p => p.custom_item)
                .filter(Boolean);

            // Fetch UOMs from Item master (single API call)
            frappe.call({
                method: "frappe.client.get_list",
                args: {
                    doctype: "Item",
                    filters: { name: ["in", item_codes] },
                    fields: ["name", "stock_uom", "description"],
                    limit_page_length: 0
                },
                callback(res) {
                    let item_map = {};
                    (res.message || []).forEach(i => {
                        item_map[i.name] = i;
                    });

                    frm.clear_table("items");

                    products.forEach(p => {
                        let row = frm.add_child("items");
                        let item_info = item_map[p.custom_item] || {};

                        row.item_code = p.custom_item || "";
                        row.item_name = p.product_name || "";
                        row.description = item_info.description || p.product_name || "";
                        row.qty = p.qty || 1;
                        row.rate = p.rate || 0;
                        row.uom = item_info.stock_uom || "Nos";
                        row.stock_uom = item_info.stock_uom || "Nos";
                        row.conversion_factor = 1;
                        row.amount = (p.qty || 1) * (p.rate || 0);
                        if (p.discount_percentage) {
                            row.discount_percentage = p.discount_percentage;
                        }
                    });

                    frm.refresh_field("items");

                    frappe.show_alert({
                        message: products.length + " product(s) loaded from CRM Deal",
                        indicator: "green"
                    });
                }
            });
        }
    });
}

