        if (!frm.is_new()) return;

        // Check if this Sales Invoice was created from a Sales Order
        let items = frm.doc.items || [];
        let so_name = null;
        for (let item of items) {
            if (item.sales_order) {
                so_name = item.sales_order;
                break;
            }
        }
        if (!so_name) return;

        // Fix: When mapping Sales Order > Sales Invoice, ERPNext async
        // get_item_details callback can override rates.
        // Wait for async ops, then re-apply from Sales Order.
        setTimeout(() => {
            frappe.after_ajax(() => {
                frappe.call({
                    method: 'frappe.client.get',
                    args: { doctype: 'Sales Order', name: so_name },
                    callback(r) {
                        if (!r.message) return;
                        let so_items = r.message.items || [];
                        let applied = 0;

                        for (const so_item of so_items) {
                            // Match by so_detail reference
                            let row = items.find(
                                i => i.so_detail === so_item.name
                            );
                            // Fallback: match by item_code
                            if (!row) {
                                row = items.find(
                                    i => i.item_code === so_item.item_code
                                );
                            }
                            if (row && so_item.rate) {
                                if (row.rate !== so_item.rate) {
                                    frappe.model.set_value(
                                        row.doctype, row.name,
                                        'rate', so_item.rate
                                    );
                                    applied++;
                                }
                                if (so_item.discount_percentage && row.discount_percentage !== so_item.discount_percentage) {
                                    frappe.model.set_value(
                                        row.doctype, row.name,
                                        'discount_percentage', so_item.discount_percentage
