	"35": "Andaman and Nicobar Islands",
	"36": "Telangana",
	"37": "Andhra Pradesh",
	"38": "Ladakh",
	"97": "Other Territory",
	"99": "Other Countries"
};

const state_to_code = {};
for (let code in state_codes) {
	state_to_code[state_codes[code]] = code;
}

frappe.ui.form.on('Address', {
	gstin: function(frm) {
		if (frm.doc.gstin && frm.doc.gstin.length >= 2) {
			let code = frm.doc.gstin.substring(0, 2);
			let state = state_codes[code];
			if (state) {
				frm.set_value('gst_state', state);
				frm.set_value('gst_state_number', code);
				if (!frm.doc.state) {
					frm.set_value('state', state);
				}
			}
		}
	},
	gst_state: function(frm) {
		if (frm.doc.gst_state) {
			let code = state_to_code[frm.doc.gst_state];
			if (code) {
				frm.set_value('gst_state_number', code);
			}
			if (frm.doc.gst_state !== frm.doc.state) {
				frm.set_value('state', frm.doc.gst_state);
			}
		} else {
			frm.set_value('gst_state_number', '');
		}
	},
	state: function(frm) {
		if ((frm.doc.country === 'India' || frm.doc.country_address === 'India') && frm.doc.state) {
			let matched_state = Object.keys(state_to_code).find(s => s.toLowerCase() === frm.doc.state.toLowerCase());
			if (matched_state && frm.doc.gst_state !== matched_state) {
				frm.set_value('gst_state', matched_state);
			}
		}
	}
});
